1	export interface MiCampConfig {
2	  baseUrl: string;
3	  apiUsername: string;
4	  apiPassword: string;
5	  merchantKey: number;
6	  register?: string | number;
7	}
8	
9	export interface MiCampCardData {
10	  CardNumber: string;
11	  ExpirationDate: string;
12	  CVV?: string;
13	  NameOnCard?: string;
14	  ZipCode?: string;
15	}
16	
17	export interface MiCampInvoiceData {
18	  InvoiceNumber: string;
19	  TotalAmount: number;
20	}
21	
22	export interface MiCampTransactionResponse {
23	  TransactionId: number;
24	  ResultCode: number;
25	  ResultText: string;
26	  ResponseMessage: string;
27	  Token?: string;
28	  CardDetails?: {
29	    AuthorizedAmount: number;
30	    AuthorizationCode: string;
31	    BINData?: {
32	      CardBrand: string;
33	      CardType: string;
34	    };
35	  };
36	}
37	
38	export interface MiCampTokenResponse {
39	  Token: string;
40	  CardNumber: string;
41	  CardType: string;
42	  ExpirationDate: string;
43	}
44	
45	const RESULT_CODES = {
46	  SUCCESS: 0,
47	  GENERIC_ERROR: -100,
48	  INVALID_CARD: -101,
49	  INSUFFICIENT_FUNDS: -102,
50	  DECLINED: -103,
51	} as const;
52	
53	export { RESULT_CODES };
54	
55	const TOKEN_CACHE_MS = 55 * 60 * 1000;
56	
57	export class MiCampClient {
58	  private config: MiCampConfig;
59	  private bearerToken: string | null = null;
60	  private tokenExpiresAt = 0;
61	
62	  constructor(config: MiCampConfig) {
63	    this.config = config;
64	  }
65	
66	  async authenticate(): Promise<string> {
67	    if (this.bearerToken && Date.now() < this.tokenExpiresAt) {
68	      return this.bearerToken;
69	    }
70	
71	    try {
72	      const response = await fetch(`${this.config.baseUrl}/api/authenticate`, {
73	        method: 'POST',
74	        headers: { 'Content-Type': 'application/json' },
75	        body: JSON.stringify({
76	          UserName: this.config.apiUsername,
77	          Password: this.config.apiPassword,
78	        }),
79	      });
80	
81	      if (!response.ok) {
82	        throw new Error(
83	          `[MiCamp] Authentication failed with status ${response.status}`,
84	        );
85	      }
86	
87	      const data = await response.json();
88	
89	      if (!data.BearerToken) {
90	        throw new Error('[MiCamp] Authentication response missing BearerToken');
91	      }
92	
93	      const token = data.BearerToken as string;
94	      this.bearerToken = token;
95	      this.tokenExpiresAt = Date.now() + TOKEN_CACHE_MS;
96	
97	      return token;
98	    } catch (error) {
99	      this.bearerToken = null;
100	      this.tokenExpiresAt = 0;
101	      throw error instanceof Error
102	        ? error
103	        : new Error(`[MiCamp] Authentication error: ${String(error)}`);
104	    }
105	  }
106	
107	  async sale(
108	    amountDollars: number,
109	    cardData: MiCampCardData,
110	    invoiceData: MiCampInvoiceData,
111	  ): Promise<MiCampTransactionResponse> {
112	    const token = await this.authenticate();
113	
114	    const body = {
115	      TransactionType: 'Sale',
116	      MerchantKey: this.config.merchantKey,
117	      ...(this.config.register != null && { Register: this.config.register }),
118	      Amount: amountDollars,
119	      CardData: {
120	        ...cardData,
121	        ExpirationDate: formatExpirationForTransaction(cardData.ExpirationDate),
122	      },
123	      InvoiceData: {
124	        InvoiceNumber: invoiceData.InvoiceNumber,
125	        TotalAmount: invoiceData.TotalAmount,
126	      },
127	    };
128	
129	    return this.postTransaction(token, body);
130	  }
131	
132	  async saleWithToken(
133	    amountDollars: number,
134	    cardToken: string,
135	    invoiceData: MiCampInvoiceData,
136	  ): Promise<MiCampTransactionResponse> {
137	    const token = await this.authenticate();
138	
139	    const body = {
140	      TransactionType: 'Sale',
141	      MerchantKey: this.config.merchantKey,
142	      ...(this.config.register != null && { Register: this.config.register }),
143	      Amount: amountDollars,
144	      Token: cardToken,
145	      InvoiceData: {
146	        InvoiceNumber: invoiceData.InvoiceNumber,
147	        TotalAmount: invoiceData.TotalAmount,
148	      },
149	    };
150	
151	    return this.postTransaction(token, body);
152	  }
153	
154	  async voidTransaction(
155	    transactionId: number,
156	  ): Promise<MiCampTransactionResponse> {
157	    const token = await this.authenticate();
158	
159	    const body = {
160	      TransactionType: 'Void',
161	      MerchantKey: this.config.merchantKey,
162	      ...(this.config.register != null && { Register: this.config.register }),
163	      OriginalTransaction: { TransactionId: transactionId },
164	    };
165	
166	    return this.postTransaction(token, body);
167	  }
168	
169	  async refund(
170	    transactionId: number,
171	    amountDollars: number,
172	  ): Promise<MiCampTransactionResponse> {
173	    const token = await this.authenticate();
174	
175	    const body = {
176	      TransactionType: 'Refund',
177	      MerchantKey: this.config.merchantKey,
178	      ...(this.config.register != null && { Register: this.config.register }),
179	      OriginalTransaction: { TransactionId: transactionId },
180	      Amount: amountDollars,
181	    };
182	
183	    return this.postTransaction(token, body);
184	  }
185	
186	  async createToken(cardData: MiCampCardData): Promise<MiCampTokenResponse> {
187	    const token = await this.authenticate();
188	    const url = `${this.config.baseUrl}/api/merchants/${this.config.merchantKey}/tokens/cards`;
189	
190	    try {
191	      const response = await fetch(url, {
192	        method: 'POST',
193	        headers: {
194	          'Content-Type': 'application/json',
195	          Authorization: `Bearer ${token}`,
196	        },
197	        body: JSON.stringify(cardData),
198	      });
199	
200	      if (!response.ok) {
201	        throw new Error(
202	          `[MiCamp] Create token failed with status ${response.status}`,
203	        );
204	      }
205	
206	      return response.json();
207	    } catch (error) {
208	      throw error instanceof Error
209	        ? error
210	        : new Error(`[MiCamp] Create token error: ${String(error)}`);
211	    }
212	  }
213	
214	  async getToken(cardToken: string): Promise<MiCampTokenResponse> {
215	    const token = await this.authenticate();
216	    const url = `${this.config.baseUrl}/api/merchants/${this.config.merchantKey}/tokens/cards/${cardToken}`;
217	
218	    try {
219	      const response = await fetch(url, {
220	        method: 'GET',
221	        headers: {
222	          Authorization: `Bearer ${token}`,
223	        },
224	      });
225	
226	      if (!response.ok) {
227	        throw new Error(
228	          `[MiCamp] Get token failed with status ${response.status}`,
229	        );
230	      }
231	
232	      return response.json();
233	    } catch (error) {
234	      throw error instanceof Error
235	        ? error
236	        : new Error(`[MiCamp] Get token error: ${String(error)}`);
237	    }
238	  }
239	
240	  async deleteToken(cardToken: string): Promise<void> {
241	    const token = await this.authenticate();
242	    const url = `${this.config.baseUrl}/api/merchants/${this.config.merchantKey}/tokens/cards/${cardToken}`;
243	
244	    try {
245	      const response = await fetch(url, {
246	        method: 'DELETE',
247	        headers: {
248	          Authorization: `Bearer ${token}`,
249	        },
250	      });
251	
252	      if (!response.ok) {
253	        throw new Error(
254	          `[MiCamp] Delete token failed with status ${response.status}`,
255	        );
256	      }
257	    } catch (error) {
258	      throw error instanceof Error
259	        ? error
260	        : new Error(`[MiCamp] Delete token error: ${String(error)}`);
261	    }
262	  }
263	
264	  private async postTransaction(
265	    bearerToken: string,
266	    body: Record<string, unknown>,
267	  ): Promise<MiCampTransactionResponse> {
268	    const url = `${this.config.baseUrl}/api/v2/transactions/bcp`;
269	
270	    try {
271	      const response = await fetch(url, {
272	        method: 'POST',
273	        headers: {
274	          'Content-Type': 'application/json',
275	          Authorization: `Bearer ${bearerToken}`,
276	        },
277	        body: JSON.stringify(body),
278	      });
279	
280	      // MiCamp returns 400 for declined transactions; response may be a full
281	      // transaction object or a simple { Message: "..." } error.
282	      const data = await response.json();
283	
284	      if (!response.ok || data.ResultCode !== RESULT_CODES.SUCCESS) {
285	        const msg =
286	          data.ResultText ??
287	          data.ResponseMessage ??
288	          data.Message ??
289	          `HTTP ${response.status}`;
290	        throw new Error(
291	          `[MiCamp] Transaction declined: ${msg} (code ${data.ResultCode ?? response.status})`,
292	        );
293	      }
294	
295	      return data;
296	    } catch (error) {
297	      throw error instanceof Error
298	        ? error
299	        : new Error(`[MiCamp] Transaction error: ${String(error)}`);
300	    }
301	  }
302	}
303	
304	const CARD_BRAND_MAP: Record<string, string> = {
305	  VISA: 'visa',
306	  MASTERCARD: 'mastercard',
307	  AMEX: 'amex',
308	  'AMERICAN EXPRESS': 'amex',
309	  DISCOVER: 'discover',
310	};
311	
312	export function normalizeMiCampCardBrand(raw: string): string {
313	  return CARD_BRAND_MAP[raw.toUpperCase()] ?? raw.toLowerCase();
314	}
315	
316	export function extractLast4(maskedOrFull: string): string {
317	  const digits = maskedOrFull.replace(/\D/g, '');
318	  return digits.slice(-4);
319	}
320	
321	export function formatExpirationForTransaction(mmyy: string): string {
322	  return mmyy.replace(/\//g, '');
323	}
324	
325	export function formatExpirationForDisplay(mmyy: string): string {
326	  const clean = mmyy.replace(/\//g, '');
327	  if (clean.length !== 4) return mmyy;
328	  return `${clean.slice(0, 2)}/${clean.slice(2)}`;
329	}
