28	async function loadMiCampConfig(flightSchoolId: string): Promise<{
29	  config: typeof schema.paymentProcessorConfigs.$inferSelect;
30	  client: MiCampClient;
31	} | null> {
32	  const config = await db.query.paymentProcessorConfigs.findFirst({
33	    where: and(
34	      eq(schema.paymentProcessorConfigs.flightSchoolId, flightSchoolId),
35	      eq(schema.paymentProcessorConfigs.processor, 'micamp'),
36	      eq(schema.paymentProcessorConfigs.isConnected, true),
37	      eq(schema.paymentProcessorConfigs.enabledBySuperAdmin, true),
38	    ),
39	  });
40	
41	  if (
42	    !config ||
43	    !config.apiUsername ||
44	    !config.apiPasswordEncrypted ||
45	    config.merchantKey == null
46	  ) {
47	    return null;
48	  }
49	
50	  const apiPassword = decrypt(config.apiPasswordEncrypted);
51	  const env = (config.environment ?? 'sandbox') as keyof typeof MICAMP_ENVS;
52	  const micampConfig: MiCampConfig = {
53	    baseUrl: MICAMP_ENVS[env] ?? MICAMP_ENVS.sandbox,
54	    apiUsername: config.apiUsername,
55	    apiPassword,
56	    merchantKey: Number(config.merchantKey),
57	  };
58	
59	  return { config, client: new MiCampClient(micampConfig) };
60	}
