86	micamp.post('/micamp/connect', requireAdmin(), async (c) => {
87	  try {
88	    const {
89	      flightSchoolId,
90	      apiUsername,
91	      apiPassword,
92	      merchantKey,
93	      environment = 'sandbox',
94	      processingFeePercent,
95	    } = await c.req.json();
96	
97	    if (!flightSchoolId || !apiUsername || !apiPassword || !merchantKey) {
98	      return c.json(
