100	          error:
101	            'Missing required fields: flightSchoolId, apiUsername, apiPassword, merchantKey',
102	        },
103	        400,
104	      );
105	    }
106	
107	    // Verify super admin has enabled MiCamp for this school
108	    const existing = await db.query.paymentProcessorConfigs.findFirst({
109	      where: and(
110	        eq(schema.paymentProcessorConfigs.flightSchoolId, flightSchoolId),
111	        eq(schema.paymentProcessorConfigs.processor, 'micamp'),
112	      ),
113	    });
114	
115	    if (!existing?.enabledBySuperAdmin) {
116	      return c.json(
117	        { error: 'MiCamp has not been enabled for this flight school by Hilo' },
118	        403,
119	      );
120	    }
121	
122	    // Validate credentials by authenticating
123	    const env = environment as keyof typeof MICAMP_ENVS;
124	    const testConfig: MiCampConfig = {
125	      baseUrl: MICAMP_ENVS[env] ?? MICAMP_ENVS.sandbox,
126	      apiUsername,
127	      apiPassword,
128	      merchantKey: Number(merchantKey),
129	    };
130	    const testClient = new MiCampClient(testConfig);
131	    await testClient.authenticate();
132	
133	    const authUser = c.get('authUser') as AuthUser;
134	    const apiPasswordEncrypted = encrypt(apiPassword);
135	
136	    const [row] = await db
137	      .insert(schema.paymentProcessorConfigs)
138	      .values({
139	        flightSchoolId,
140	        processor: 'micamp',
141	        apiUsername,
142	        apiPasswordEncrypted,
143	        merchantKey: Number(merchantKey),
144	        environment,
145	        isConnected: true,
146	        connectedAt: new Date(),
147	        connectedByUserId: authUser.id,
148	        ...(processingFeePercent != null
149	          ? { processingFeePercent: String(processingFeePercent) }
150	          : {}),
151	      })
152	      .onConflictDoUpdate({
153	        target: [
154	          schema.paymentProcessorConfigs.flightSchoolId,
155	          schema.paymentProcessorConfigs.processor,
156	        ],
157	        set: {
158	          apiUsername,
159	          apiPasswordEncrypted,
160	          merchantKey: Number(merchantKey),
161	          environment,
162	          isConnected: true,
163	          connectedAt: new Date(),
164	          connectedByUserId: authUser.id,
165	          ...(processingFeePercent != null
166	            ? { processingFeePercent: String(processingFeePercent) }
167	            : {}),
168	          updatedAt: new Date(),
169	        },
170	      })
171	      .returning();
172	
173	    return c.json({
174	      success: true,
175	      environment: row.environment,
176	      merchantKey: row.merchantKey,
177	    });
178	  } catch (e: unknown) {
179	    const msg = e instanceof Error ? e.message : 'Unknown error';
180	    console.error('[MiCamp] Connect error:', e);
181	    return c.json({ error: msg }, 502);
182	  }
183	});
